def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0
    import heapq

    times = sorted({t for start, end, _pay in jobs for t in (start, end)})
    pos = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph: list[list[list[int]]] = [[] for _ in range(n)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)
    for start, end, pay in jobs:
        add_edge(pos[start], pos[end], 1, -pay)

    INF = 10**18
    pot = [INF] * n
    pot[0] = 0
    for u in range(n):
        if pot[u] >= INF // 2:
            continue
        for v, cap, cost, _rev in graph[u]:
            if cap > 0 and pot[u] + cost < pot[v]:
                pot[v] = pot[u] + cost

    sink = n - 1
    total = 0
    for _ in range(k):
        dist = [INF] * n
        dist[0] = 0
        prev_node = [-1] * n
        prev_edge = [-1] * n
        finalized = [False] * n
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if finalized[u] or d != dist[u]:
                continue
            finalized[u] = True
            for ei, (v, cap, cost, _rev) in enumerate(graph[u]):
                if cap <= 0 or finalized[v]:
                    continue
                nd = d + cost + pot[u] - pot[v]
                if nd < dist[v]:
                    dist[v] = nd
                    prev_node[v] = u
                    prev_edge[v] = ei
                    heapq.heappush(heap, (nd, v))
        if not finalized[sink]:
            break
        real = 0
        v = sink
        while v != 0:
            u = prev_node[v]
            ei = prev_edge[v]
            real += graph[u][ei][2]
            v = u
        if real >= 0:
            break
        v = sink
        while v != 0:
            u = prev_node[v]
            ei = prev_edge[v]
            rev = graph[u][ei][3]
            graph[u][ei][1] -= 1
            graph[v][rev][1] += 1
            v = u
        for i in range(n):
            if finalized[i] and dist[i] < INF // 2:
                pot[i] += dist[i]
        total += -real
    return total
